def calcular_descuento(total_centavos: int, porcentaje: int) -> int:
    if total_centavos < 0 or not 0 <= porcentaje <= 100:
        raise ValueError("Parámetros de descuento fuera de rango")
    # Aritmética entera en centavos para evitar imprecisión de punto flotante
    return total_centavos - (total_centavos * porcentaje) // 100
